from AlgorithmImports import *
import math


class ExactStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.spy_lot = 0
        self.aapl_lot = 0

        self.spy_pending_order_id = None
        self.aapl_pending_order_id = None

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.spy_crossed_above = False
        self.spy_crossed_below = False

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.current_aapl_close = None

    def OnData(self, data):
        self._update_market_state(data)

        if self.IsWarmingUp:
            return

        if not self._all_bars_present(data):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        self._evaluate_sells()
        self._evaluate_buys()

    def _all_bars_present(self, data):
        symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]
        return all(data.Bars.ContainsKey(symbol) for symbol in symbols)

    def _update_market_state(self, data):
        if data.Bars.ContainsKey(self.spy):
            spy_close = float(data.Bars[self.spy].Close)
            current_sma = (
                float(self.spy_sma.Current.Value)
                if self.spy_sma.IsReady
                else None
            )

            self.spy_crossed_above = False
            self.spy_crossed_below = False

            if (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and current_sma is not None
            ):
                self.spy_crossed_above = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_close > current_sma
                )
                self.spy_crossed_below = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and spy_close < current_sma
                )

            self.previous_spy_close = spy_close
            self.previous_spy_sma = current_sma
        else:
            self.previous_spy_close = None
            self.previous_spy_sma = None
            self.spy_crossed_above = False
            self.spy_crossed_below = False

        if data.Bars.ContainsKey(self.aapl):
            aapl_close = float(data.Bars[self.aapl].Close)
            self.current_aapl_close = aapl_close

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close
        else:
            self.previous_aapl_close = None
            self.current_aapl_close = None
            self.aapl_red_streak = 0

    def _evaluate_sells(self):
        if (
            self.spy_lot > 0
            and self.spy_pending_order_id is None
            and self.spy_crossed_below
        ):
            self._submit_order(
                self.spy,
                -self.spy_lot,
                "SPY Strategy A sell"
            )

        if (
            self.aapl_lot > 0
            and self.aapl_pending_order_id is None
            and float(self.aapl_rsi.Current.Value) > 60
        ):
            self._submit_order(
                self.aapl,
                -self.aapl_lot,
                "AAPL Strategy B sell"
            )

    def _evaluate_buys(self):
        if (
            self.spy_lot == 0
            and self.spy_pending_order_id is None
            and self.spy_crossed_above
        ):
            spy_close = float(self.Securities[self.spy].Close)
            quantity = int(
                math.floor(
                    0.40 * float(self.Portfolio.TotalPortfolioValue)
                    / spy_close
                )
            )

            if quantity > 0:
                self._submit_order(
                    self.spy,
                    quantity,
                    "SPY Strategy A buy"
                )

        if (
            self.aapl_lot == 0
            and self.aapl_pending_order_id is None
            and self.aapl_red_streak >= 3
        ):
            if float(self.Portfolio.Cash) >= 20000:
                quantity = int(
                    math.floor(20000 / self.current_aapl_close)
                )

                if quantity > 0:
                    self._submit_order(
                        self.aapl,
                        quantity,
                        "AAPL Strategy B buy"
                    )

    def _submit_order(self, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if symbol == self.spy:
            self.spy_pending_order_id = ticket.OrderId
        elif symbol == self.aapl:
            self.aapl_pending_order_id = ticket.OrderId

    def OnOrderEvent(self, orderEvent):
        if orderEvent.Symbol == self.spy:
            self.spy_lot += int(orderEvent.FillQuantity)

            if orderEvent.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                if orderEvent.OrderId == self.spy_pending_order_id:
                    self.spy_pending_order_id = None

        elif orderEvent.Symbol == self.aapl:
            self.aapl_lot += int(orderEvent.FillQuantity)

            if orderEvent.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                if orderEvent.OrderId == self.aapl_pending_order_id:
                    self.aapl_pending_order_id = None

        self.spy_lot = max(0, self.spy_lot)
        self.aapl_lot = max(0, self.aapl_lot)

